/* @autogenerated */
import {
  computed,
  Directive,
  effect,
  forwardRef,
  inject,
  Injector,
  input,
  OnDestroy,
  OnInit,
  signal,
} from '@angular/core';
import {
  AbstractControl,
  ControlContainer,
  ControlValueAccessor,
  FormControl,
  FormControlDirective,
  FormControlName,
  FormGroup,
  NG_VALIDATORS,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgModel,
  ValidationErrors,
  Validator,
  Validators,
} from '@angular/forms';
import { MatFormFieldAppearance } from '@angular/material/form-field';
import { TranslocoService } from '@jsverse/transloco';
import { Subscription } from 'rxjs';

/** Un error de validación con sus parámetros (`minlength` → `{ requiredLength, actualLength }`). */
export interface EditableError {
  key: string;
  params: Record<string, unknown>;
}

@Directive({ host: { class: 'editable' } })
export abstract class BaseEditable<T> implements ControlValueAccessor, Validator, OnInit, OnDestroy {
  // Método estático para generar los providers
  static getAccessorProvider(subClass: any) {
    return [
      {
        provide: NG_VALUE_ACCESSOR,
        useExisting: forwardRef(() => subClass),
        multi: true,
      },
    ];
  }
  static getValidableAccessorProvider(subClass: any) {
    return [
      {
        provide: NG_VALUE_ACCESSOR,
        useExisting: forwardRef(() => subClass),
        multi: true,
      },
      {
        provide: NG_VALIDATORS,
        useExisting: forwardRef(() => subClass),
        multi: true,
      },
    ];
  }

  label = input<string>();
  visible = input<boolean>(true);
  showHiddenMark = input<boolean>(false);
  /** Clave de traducción de la ayuda; sin ella se usa `<label>.hint` si existe. */
  hint = input<string>();
  /** Apariencia del mat-form-field; sin ella, la de MAT_FORM_FIELD_DEFAULT_OPTIONS. */
  appearance = input<MatFormFieldAppearance>();

  readonly required = signal(false);
  protected value = signal<T | null>(null);
  protected errors = signal<ValidationErrors | null>(null);
  protected disabled = signal(false);
  protected pending = signal(false);
  protected touched = signal(false);
  protected control!: FormControl;
  readonly errorList = computed<EditableError[]>(() =>
    Object.entries(this.errors() ?? {}).map(([key, params]) => ({
      key,
      params: typeof params === 'object' && params !== null ? params : {},
    })),
  );

  private onChange = (_: T | null) => {};
  private onTouched = () => {};
  private onValidate = () => {};

  private injector = inject(Injector);
  private transloco = inject(TranslocoService);
  private ngModelSyncSubscription?: Subscription;
  private statusSubscription?: Subscription;
  private binded: FormControl[] = [];

  constructor() {
    effect(() => {
      if (this.touched()) {
        this.onTouched();
      }
    });
    effect(() => {
      if (this.pending()) {
        this.control.markAsPending();
      } else {
        this.control.updateValueAndValidity();
      }
    });
    effect(() => {
      const errors = this.errors();
      this.onValidate();
    });
  }

  ngOnInit() {
    const ngControl = this.injector.get(NgControl, null, {
      self: true,
      optional: true,
    });
    if (ngControl instanceof NgModel) {
      this.control = ngControl.control;
      this.ngModelSyncSubscription = ngControl.control.valueChanges.subscribe((value) => {
        if (ngControl.model !== value || ngControl.viewModel !== value) {
          ngControl.viewToModelUpdate(value);
        }
      });
    } else if (ngControl instanceof FormControlDirective) {
      this.control = ngControl.control;
    } else if (ngControl instanceof FormControlName) {
      const container = this.injector.get(ControlContainer).control as FormGroup;
      this.control = container.controls[ngControl.name!] as FormControl;
    } else {
      this.control = new FormControl();
    }
    this.required.set(this.control.hasValidator(Validators.required));
    this.statusSubscription = this.control.statusChanges.subscribe(() => {
      // Angular no avisa de setValidators: se recalcula en el updateValueAndValidity que lo acompaña
      this.required.set(this.control.hasValidator(Validators.required));
      const prev = JSON.stringify(this.errors() || {});
      const curr = JSON.stringify(this.control.errors || {});
      if (prev !== curr) {
        this.errors.set(this.control.errors);
      }
      this.binded.forEach((ctr) => {
        if (this.control.enabled) {
          ctr.enable({ onlySelf: true });
        } else {
          ctr.disable({ onlySelf: true });
        }
      });
    });
  }

  /** Clave del mensaje de un error: la del campo, la común `validation.<error>` o `validation.invalid`. */
  errorKey(error: EditableError): string {
    const own = `${this.label()}.error.${error.key}`;
    if (this.hasTranslation(own)) {
      return own;
    }
    // Los subformularios prefijan el error con el campo (`name.required`)
    const common = `validation.${error.key.split('.').pop()}`;
    return this.hasTranslation(common) ? common : 'validation.invalid';
  }

  /** Clave de la ayuda del campo, o null si no tiene. */
  hintKey(): string | null {
    const explicit = this.hint();
    if (explicit) {
      return explicit;
    }
    const key = `${this.label()}.hint`;
    return this.hasTranslation(key) ? key : null;
  }

  private hasTranslation(key: string): boolean {
    return this.transloco.getTranslation(this.transloco.getActiveLang())[key] !== undefined;
  }

  protected updateValue(value: T | null): void {
    const prev = JSON.stringify(this.value());
    const curr = JSON.stringify(value);
    if (prev !== curr) {
      this.value.set(value);
      this.onChange(value);
    }
  }

  protected refresh() {
    const dirty = this.control.dirty;
    this.onChange(this.value());
    setTimeout(() => {
      if (!dirty) {
        this.control.markAsPristine();
      }
      this.control.updateValueAndValidity();
    });
  }

  protected bind(controls: FormControl[]) {
    this.binded.push(...controls);
  }

  registerOnValidatorChange(fn: () => void): void {
    this.onValidate = fn;
  }

  validate(_: AbstractControl): ValidationErrors | null {
    return this.errors();
  }

  ngOnDestroy() {
    this.ngModelSyncSubscription?.unsubscribe();
    this.statusSubscription?.unsubscribe();
  }

  writeValue(value: T): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: T | null) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }
}
